// ─── File: TransferService.java ───
package com.bank.sysdesign;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class TransferService {
    private static final Logger log = Logger.getLogger("SysDesign");
    private final AccountRepository repo;
    // idempotency keys we have already processed
    private final Set<String> processedKeys = new HashSet<>();

    public TransferService(AccountRepository repo) { this.repo = repo; }

    // STEP 3 deep-dive: atomic, idempotent transfer
    public synchronized void transfer(String from, String to, BigDecimal amount, String idemKey) {
        if (processedKeys.contains(idemKey)) {
            log.warning(() -> "Duplicate request " + idemKey + " ignored (idempotent)");
            return;
        }
        Account debtor = repo.findById(from);
        Account creditor = repo.findById(to);
        try {
            debtor.debit(amount);    // both happen or neither (single-thread critical section)
            creditor.credit(amount);
            processedKeys.add(idemKey);
            log.info(() -> "Transferred Rs." + amount + " " + from + " -> " + to);
        } catch (RuntimeException e) {
            log.log(Level.SEVERE, "Transfer failed, rolled back", e);
            throw e;
        }
    }
}
