// ─── File: CapacityPlanner.java ───
package com.bank.capacity;

public class CapacityPlanner {

    // queries per second at peak
    public long estimateQps(long dailyRequests, int peakFactor) {
        long avg = dailyRequests / 86_400L;
        return avg * peakFactor;
    }

    // total storage bytes for the retention window
    public long estimateStorage(long bytesPerRecord, long recordsPerDay, long retentionDays) {
        return bytesPerRecord * recordsPerDay * retentionDays;
    }

    // peak bandwidth in bytes per second
    public long estimateBandwidth(long responseBytes, long peakQps) {
        return responseBytes * peakQps;
    }

    // number of servers, rounded up, plus one for redundancy
    public long estimateServers(long peakQps, long serverCapacityQps) {
        long needed = (peakQps + serverCapacityQps - 1) / serverCapacityQps; // ceil
        return needed + 1;  // +1 buffer for failover
    }
}
```

