// ─── File: TokenBucketLimiter.java ───
package com.bank.ratelimit;

import java.util.concurrent.ConcurrentHashMap;

public class TokenBucketLimiter {
    private final double ratePerSec;   // steady refill rate
    private final double capacity;     // max burst
    // In production this map lives in Redis with an atomic Lua script.
    private final ConcurrentHashMap<String, Bucket> buckets = new ConcurrentHashMap<>();

    public TokenBucketLimiter(double ratePerSec, double capacity) {
        this.ratePerSec = ratePerSec;
        this.capacity = capacity;
    }

    public synchronized boolean allow(String client) {
        Bucket b = buckets.computeIfAbsent(client,
            k -> new Bucket(capacity, System.nanoTime()));
        long now = System.nanoTime();
        double elapsedSec = (now - b.lastRefillNanos) / 1_000_000_000.0;
        b.tokens = Math.min(capacity, b.tokens + elapsedSec * ratePerSec); // refill
        b.lastRefillNanos = now;
        if (b.tokens >= 1.0) {
            b.tokens -= 1.0;   // consume a token
            return true;
        }
        return false;          // throttle: HTTP 429
    }
}
