// ─── File: NotificationDispatcher.java ───
package com.bank.notify;

import java.util.*;
import java.util.logging.*;

public class NotificationDispatcher {
    private static final Logger log = Logger.getLogger("Notify");
    private final UserPreferenceStore prefs;
    private final TemplateEngine templates;
    private final ChannelSender sender = new ChannelSender();
    private final Set<String> delivered = new HashSet<>(); // idempotency
    private static final int MAX_RETRIES = 3;

    public NotificationDispatcher(UserPreferenceStore prefs, TemplateEngine templates) {
        this.prefs = prefs; this.templates = templates;
    }

    public void dispatch(NotificationEvent e) {
        if (delivered.contains(e.getId())) {   // dedup on redelivery
            log.warning(() -> "Duplicate " + e.getId() + " ignored");
            return;
        }
        String body = templates.render(e.getTemplateKey(), e.getData());
        log.info(() -> "[" + e.getPriority() + "] dispatching " + e.getId());

        for (String channel : prefs.channelsFor(e.getUserId())) {
            if (sendWithRetry(channel, e.getUserId(), body)) {
                delivered.add(e.getId());
                return;  // first successful channel wins
            }
        }
        log.severe(() -> "All channels failed for " + e.getId() + " -> dead-letter queue");
    }

    private boolean sendWithRetry(String channel, String userId, String body) {
        for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
            if (sender.send(channel, userId, body)) return true;
            int a = attempt;
            log.warning(() -> "Retry " + a + " for " + channel + " to " + userId);
        }
        return false;
    }
}
