// ─── File: AccountLedger.java ───
package com.bank.payment;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

public class AccountLedger {
    private final Map<String, BigDecimal> available = new HashMap<>();
    private final Map<String, BigDecimal> held = new HashMap<>();
    private final Map<String, String> holders = new HashMap<>();
    private final List<LedgerEntry> entries = new ArrayList<>(); // append-only

    public void open(String id, String holder, BigDecimal opening) {
        available.put(id, opening); held.put(id, BigDecimal.ZERO); holders.put(id, holder);
    }

    // reserve: available -> held (double-spend safe within synchronized service)
    public void reserve(String account, BigDecimal amount) {
        BigDecimal avail = available.get(account);
        if (avail.compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient available in " + account);
        available.put(account, avail.subtract(amount));
        held.put(account, held.get(account).add(amount));
    }

    // settle: remove from held (money leaves); used on capture
    public void settle(String account, BigDecimal amount) {
        held.put(account, held.get(account).subtract(amount));
    }

    public void credit(String account, BigDecimal amount) {
        available.put(account, available.get(account).add(amount));
    }

    public void append(LedgerEntry e) { entries.add(e); }

    public void print(Logger log) {
        log.info("Ledger entries (append-only, double-entry):");
        entries.forEach(e -> log.info(() -> "  " + e));
        BigDecimal sum = entries.stream().map(LedgerEntry::signed)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        log.info(() -> "Ledger balances to zero: " + (sum.compareTo(BigDecimal.ZERO) == 0));
        available.forEach((k,v) -> log.info(() -> "  " + k + " available=" + v + " held=" + held.get(k)));
    }
}
