// ─── File: PaymentService.java ───
package com.bank.payment;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class PaymentService {
    private static final Logger log = Logger.getLogger("Payment");
    private final AccountLedger ledger;
    private final IdempotencyStore idem;
    private final Map<String, String[]> payments = new HashMap<>(); // id -> [from,to,amount]

    public PaymentService(AccountLedger ledger, IdempotencyStore idem) {
        this.ledger = ledger; this.idem = idem;
    }

    // idempotent authorize: reserves payer funds, records AUTH double entry
    public synchronized PaymentResult authorize(String idemKey, String from, String to, BigDecimal amount) {
        PaymentResult prior = idem.get(idemKey);
        if (prior != null) { log.warning(() -> "Idempotent hit " + idemKey); return prior; }

        String paymentId = "PAY-" + UUID.randomUUID().toString().substring(0, 8);
        ledger.reserve(from, amount);  // double-spend prevention: atomic reserve
        ledger.append(new LedgerEntry(paymentId, from, LedgerEntry.Direction.DEBIT, amount, "AUTH"));
        ledger.append(new LedgerEntry(paymentId, to, LedgerEntry.Direction.CREDIT, amount, "AUTH"));
        payments.put(paymentId, new String[]{from, to, amount.toPlainString()});

        PaymentResult result = new PaymentResult(paymentId, "AUTHORIZED");
        idem.put(idemKey, result);
        log.info(() -> "AUTHORIZED " + paymentId + " Rs." + amount);
        return result;
    }

    public synchronized void capture(String paymentId) {
        String[] p = payments.get(paymentId);
        BigDecimal amount = new BigDecimal(p[2]);
        ledger.settle(p[0], amount);     // payer held -> gone
        ledger.credit(p[1], amount);      // payee receives
        ledger.append(new LedgerEntry(paymentId, p[0], LedgerEntry.Direction.DEBIT, amount, "CAPTURE"));
        ledger.append(new LedgerEntry(paymentId, p[1], LedgerEntry.Direction.CREDIT, amount, "CAPTURE"));
        log.info(() -> "CAPTURED " + paymentId);
    }

    public synchronized void refund(String paymentId, BigDecimal amount) {
        String[] p = payments.get(paymentId);
        ledger.credit(p[0], amount);      // payer gets money back
        ledger.append(new LedgerEntry(paymentId, p[1], LedgerEntry.Direction.DEBIT, amount, "REFUND"));
        ledger.append(new LedgerEntry(paymentId, p[0], LedgerEntry.Direction.CREDIT, amount, "REFUND"));
        log.info(() -> "REFUNDED Rs." + amount + " on " + paymentId);
    }
}
