        List<byte[]> chunks = new ArrayList<>();
        for (int off = 0; off < file.length; off += CHUNK_SIZE)
            chunks.add(Arrays.copyOfRange(file, off, Math.min(off + CHUNK_SIZE, file.length)));
        return chunks;
