// ─── File: FileStorageService.java ───
package com.bank.storage;

import java.util.*;
import java.util.logging.*;

public class FileStorageService {
    private static final Logger log = Logger.getLogger("Storage");
    private final Chunker chunker = new Chunker();
    private final BlobStore blobs = new BlobStore();
    private final MetadataStore meta = new MetadataStore();

    public String upload(String fileId, String owner, byte[] content, Set<String> readers) {
        List<String> hashes = new ArrayList<>();
        for (byte[] chunk : chunker.split(content)) {
            String h = chunker.hash(chunk);
            blobs.putIfAbsent(h, chunk);   // dedup by content hash
            hashes.add(h);
        }
        long version = meta.nextVersion(fileId);
        meta.save(fileId, new FileMetadata(fileId, owner, version, hashes, readers));
        log.info(() -> "stored " + fileId + " v" + version + " with " + hashes.size() + " chunks");
        return fileId;
    }

    public byte[] download(String fileId, long version, String user) {
        FileMetadata m = meta.get(fileId, version);
        if (m == null) throw new NoSuchElementException("no such file/version");
        if (!m.canRead(user)) throw new SecurityException(user + " may not read " + fileId);
        // reassemble from chunks
        int total = 0; List<byte[]> parts = new ArrayList<>();
        for (String h : m.getChunkHashes()) { byte[] b = blobs.get(h); parts.add(b); total += b.length; }
        byte[] out = new byte[total]; int pos = 0;
        for (byte[] b : parts) { System.arraycopy(b, 0, out, pos, b.length); pos += b.length; }
        return out;
    }

    public int uniqueChunkCount() { return blobs.size(); }
    public List<Long> versions(String fileId) { return meta.versions(fileId); }
}
