```java
// ─── File: Trie.java ───
package com.bank.autocomplete;

import java.util.*;
import java.util.stream.*;

public class Trie {
    private final TrieNode root = new TrieNode();
    private final int k;
    private final Map<String, Long> frequencies = new HashMap<>();

    public Trie(int k) { this.k = k; }

    public void insert(String query, long freq) {
        frequencies.merge(query, freq, Long::sum);
        TrieNode node = root;
        for (char c : query.toCharArray())
            node = node.children.computeIfAbsent(c, x -> new TrieNode());
        node.isWord = true;
        node.frequency = frequencies.get(query);
    }

    public void addFrequency(String query, long delta) { insert(query, delta); }

    private TrieNode walk(String prefix) {
        TrieNode node = root;
        for (char c : prefix.toCharArray()) {
            node = node.children.get(c);
            if (node == null) return null;
        }
        return node;
    }

    public List<String> suggest(String prefix) {
        TrieNode node = walk(prefix);
        return node == null ? List.of() : node.topK;
    }

    // batched job: recompute top-K lists for every node from frequencies
    public void recomputeTopK() {
        recompute(root, new StringBuilder());
    }
    private List<String> recompute(TrieNode node, StringBuilder path) {
        List<Map.Entry<String,Long>> below = new ArrayList<>();
        if (node.isWord) below.add(Map.entry(path.toString(), node.frequency));
        for (var e : node.children.entrySet()) {
            path.append(e.getKey());
            for (String w : recompute(e.getValue(), path))
                below.add(Map.entry(w, frequencies.getOrDefault(w, 0L)));
            path.deleteCharAt(path.length() - 1);
        }
        node.topK = below.stream()
            .sorted(Map.Entry.<String,Long>comparingByValue().reversed())
            .limit(k).map(Map.Entry::getKey).collect(Collectors.toList());
        return node.topK;
    }
}
