package com.bank.scheduler;

import java.util.*;
import java.util.logging.*;

public class Scheduler {
    private static final Logger log = Logger.getLogger("Sched");
    private final JobStore store;
    public Scheduler(JobStore store) { this.store = store; }

    // find due jobs and claim each with a lease before handing to workers
    public void dispatchDue(WorkerPool workers, long now) {
        for (Job j : store.dueJobs(now, 100)) {
            if (claim(j, "worker-" + (j.hashCode() & 7), 5000)) {
                workers.submit(j);
            }
        }
    }

    private boolean claim(Job j, String workerId, long leaseMs) {
        if (j.state() != Job.State.PENDING) return false;  // atomic in DB (CAS)
        j.setState(Job.State.RUNNING);
        j.setLeaseOwner(workerId);
        j.setLeaseExpiry(System.currentTimeMillis() + leaseMs);
        log.fine(() -> "claimed " + j.id() + " by " + workerId);
        return true;
    }
}
