        PartitionedCounter counter = new PartitionedCounter(3); // 3 owners/partitions
        Deduper deduper = new Deduper();
        RollingWindow window = new RollingWindow(300_000L, 5_000L); // 5min window, 5s lateness

        // Feature engagement events (itemId = feature). Partition by item key.
        List<EngagementEvent> events = List.of(
            new EngagementEvent("e1","transfer",5,t0),
            new EngagementEvent("e2","balance",1,t0+1000),
            new EngagementEvent("e3","transfer",5,t0+2000),
            new EngagementEvent("e4","billpay",3,t0+3000),
            new EngagementEvent("e5","balance",1,t0+4000),
            new EngagementEvent("e3","transfer",5,t0+2000)   // DUPLICATE eventId
        );

        for (EngagementEvent e : events) {
            if (!deduper.firstSeen(e.eventId())) {
                log.warning(() -> "dedup: " + e.eventId() + " already counted");
                continue;
            }
            window.admit(e, t0 + 4000);              // current watermark-ish time
            counter.count(e.itemId(), e.weight());   // routed to item's owner
        }

        // A LATE event arriving after main batch but within allowed lateness
        EngagementEvent late = new EngagementEvent("e6","billpay",3,t0+500);
        if (deduper.firstSeen(late.eventId()) && window.admit(late, t0+4000)) {
            counter.count(late.itemId(), late.weight());
            log.info(() -> "late event e6 accepted into window");
        }

        // Each owner emits local top-2; merge to global top-2
        TopKMerger merger = new TopKMerger();
        List<Map.Entry<String,Long>> global = merger.merge(counter.localTopK(2), 2);

        // Publish an atomic versioned snapshot
        SnapshotStore store = new SnapshotStore();
        store.publish(1, global, t0 + 4000);
        // An older job must NOT overwrite the newer snapshot
        store.publish(0, List.of(), t0);   // rejected (older version)

        var snap = store.current();
        log.info(() -> "Top-K snapshot v" + snap.version() + " (generatedAt=" + snap.generatedAt() + "): " + snap.ranking());
    }
}

