// ─── File: TopKMerger.java ───
package com.bank.leaderboard;

import java.util.*;

public class TopKMerger {
    // merge per-owner local top-K into a global top-K with deterministic tie-break
    public List<Map.Entry<String,Long>> merge(List<List<Map.Entry<String,Long>>> locals, int k) {
        Map<String,Long> combined = new HashMap<>();
        for (var local : locals)
            for (var e : local) combined.merge(e.getKey(), e.getValue(), Long::sum);
        List<Map.Entry<String,Long>> all = new ArrayList<>(combined.entrySet());
        // tie-break: score desc, then itemId asc (deterministic)
        all.sort((a,b) -> {
            int byScore = Long.compare(b.getValue(), a.getValue());
            return byScore != 0 ? byScore : a.getKey().compareTo(b.getKey());
        });
        return all.subList(0, Math.min(k, all.size()));
    }
}
