public class SnapshotStore {
    private static final Logger log = Logger.getLogger("Leader");
    public record Snapshot(long version, List<Map.Entry<String,Long>> ranking, long generatedAt) {}
    private volatile Snapshot current = new Snapshot(-1, List.of(), 0);

    // atomic publish: reject if an older version tries to overwrite a newer one
    public synchronized void publish(long version, List<Map.Entry<String,Long>> ranking, long generatedAt) {
        if (version <= current.version()) {
            log.warning(() -> "rejecting stale snapshot v" + version + " (current v" + current.version() + ")");
            return;
        }
        current = new Snapshot(version, ranking, generatedAt);  // atomic pointer flip
        log.info(() -> "published snapshot v" + version);
    }
    public Snapshot current() { return current; }
}
