    public String serve(String path) {
        CacheEntry e = cache.get(path);
        if (e != null && !e.isExpired()) {
            log.info(() -> id + " HIT " + path);
            return e.body();
        }
        String body = origin.fetch(path);           // miss → origin
        cache.put(path, new CacheEntry(body, TTL));
        log.info(() -> id + " MISS->cached " + path);
        return body;
    }
    public void invalidate(String path) {
        cache.remove(path);
        log.warning(() -> id + " invalidated " + path);
    }
}
