package com.bank.messaging;

import java.util.*;

public class Topic {
    private final String name;
    private final int partitionCount;
    private final List<Deque<String>> partitions = new ArrayList<>();

    public Topic(String name, int partitionCount) {
        this.name = name; this.partitionCount = partitionCount;
        for (int i = 0; i < partitionCount; i++) partitions.add(new ArrayDeque<>());
    }
    public int partitionCount() { return partitionCount; }
    public int partitionFor(String key) { return Math.abs(key.hashCode()) % partitionCount; }
    public void append(int partition, String message) { partitions.get(partition).addLast(message); }
    public Deque<String> partition(int i) { return partitions.get(i); }
}
