package com.bank.messaging;

import java.util.*;
import java.util.logging.*;

public class IdempotentConsumer {
    private static final Logger log = Logger.getLogger("MQ");
    private final String id;
    private final DeadLetterQueue dlq;
    private final Set<String> processed = new HashSet<>(); // dedup by message id
    private static final int MAX_RETRIES = 2;

    public IdempotentConsumer(String id, DeadLetterQueue dlq) { this.id = id; this.dlq = dlq; }

    public void consume(int partition, String message) {
        String msgId = message.split(":")[0];
        if (processed.contains(msgId)) {       // at-least-once → dedup
            log.warning(() -> id + " dedup " + msgId + " (already processed)");
            return;
        }
        int attempts = 0;
        while (true) {
            try {
                if (message.startsWith("POISON")) throw new RuntimeException("bad payload");
                processed.add(msgId);
                log.info(() -> id + " processed p" + partition + " " + message);
                return;
            } catch (RuntimeException e) {
                if (++attempts > MAX_RETRIES) {
                    dlq.add(message);
                    log.severe(() -> id + " DLQ'd after retries: " + message);
                    return;
                }
                int a = attempts;
                log.warning(() -> id + " retry " + a + " for " + message);
            }
        }
    }
}
