// ─── File: ConsistentHashRing.java ───
package com.bank.hashing;

import java.util.*;

public class ConsistentHashRing {
    private final TreeMap<Integer, String> ring = new TreeMap<>();
    private final int vnodes;   // virtual nodes per physical node for even spread

    public ConsistentHashRing(int vnodes) { this.vnodes = vnodes; }

    public void addNode(String node) {
        for (int i = 0; i < vnodes; i++) ring.put(hash(node + "#" + i), node);
    }
    public void removeNode(String node) {
        for (int i = 0; i < vnodes; i++) ring.remove(hash(node + "#" + i));
    }
    public String nodeFor(String key) {
        if (ring.isEmpty()) return null;
        int h = hash(key);
        Map.Entry<Integer,String> e = ring.ceilingEntry(h);   // first node clockwise
        return (e != null ? e : ring.firstEntry()).getValue(); // wrap around the ring
    }
    private int hash(String s) {
        // simple stable hash for the demo; production uses MD5/murmur
        int h = 0;
        for (char c : s.toCharArray()) h = 31 * h + c;
        return Math.abs(h);
    }
}
