public class Failover {
    private static final Logger log = Logger.getLogger("Repl");

    // promote a replica to primary, fence the old primary to avoid split-brain
    public Node promote(Node oldPrimary, List<Node> replicas) {
        oldPrimary.fence();            // old primary can no longer accept writes
        oldPrimary.setPrimary(false);
        Node chosen = replicas.get(0); // in production: the most up-to-date replica
        chosen.setPrimary(true);
        log.warning(() -> "promoted " + chosen.name() + "; fenced " + oldPrimary.name());
        return chosen;
    }
}
