public class ApStore {
    private static final Logger log = Logger.getLogger("CAP");
    private final Cluster cluster;
    private final Map<String,String> store = new HashMap<>();
    public ApStore(Cluster cluster) { this.cluster = cluster; }

    public void seed(String key, String value) { store.put(key, value); }

    public String read(String key) {
        // never errors; returns possibly stale local value during a partition
        return store.getOrDefault(key, "<unknown>");
    }
    public void reconcile(String authoritativeValue, String key) {
        store.put(key, authoritativeValue);   // eventual consistency: converge to truth
        log.info(() -> "AP reconciled " + key + " to " + authoritativeValue);
    }
}
