package com.bank.dbchoice;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// Relational + ACID: tables, enforced balance, transactional transfer + audit.
public class SqlAccountStore {
    private static final Logger log = Logger.getLogger("DBChoice");
    private final Map<String, BigDecimal> accounts = new LinkedHashMap<>();
    private final List<String> auditTable = new ArrayList<>();

    public void open(String id, BigDecimal opening) { accounts.put(id, opening); }

    // atomic: debit, credit, and audit all succeed or all fail
    public synchronized void transferWithAudit(String from, String to, BigDecimal amount) {
        BigDecimal fromBal = accounts.get(from);
        if (fromBal.compareTo(amount) < 0) throw new IllegalStateException("insufficient funds");
        accounts.put(from, fromBal.subtract(amount));
        accounts.put(to, accounts.get(to).add(amount));
        auditTable.add("TRANSFER " + from + "->" + to + " Rs." + amount);
        log.info(() -> "SQL ACID transfer committed " + from + "->" + to);
    }

    // relational-style aggregate report (join/aggregate territory)
    public String report() {
        BigDecimal total = accounts.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        return "accounts=" + accounts + " auditCount=" + auditTable.size() + " total=" + total;
    }
}
