// ─── File: BuildVsBuyAdvisor.java ───
package com.bank.decision;

public class BuildVsBuyAdvisor {

    // weigh the factors and return a recommendation with rationale
    public String recommend(Capability c) {
        // 1. Data sovereignty / lock-in risk can force keeping it in-house/controlled
        if (c.dataSovereigntyRisk && c.coreDifferentiator)
            return c.name + " => BUILD (sensitive data + sovereignty/lock-in risk + core)";

        // 2. Core differentiator we can build AND maintain → build the edge
        if (c.coreDifferentiator && c.teamHasExpertise)
            return c.name + " => BUILD (competitive differentiator, retain the edge)";

        // 3. Commodity + urgent → buy for speed
        if (!c.coreDifferentiator && c.urgentTimeToMarket)
            return c.name + " => BUY (commodity, time-to-market; avoid maintaining non-core)";

        // 4. Otherwise decide by total cost of ownership
        if (c.buyTco <= c.buildTco)
            return c.name + " => BUY (lower TCO; 'build it better' costs maintenance forever)";
        return c.name + " => BUILD (lower TCO even accounting for maintenance)";
    }
}
