package com.bank.consistency;

import java.util.*;

// Strong consistency: single leader; reads always see the latest committed write.
public class StrongStore {
    private final Map<String,String> leader = new HashMap<>();
    public void write(String key, String value) { leader.put(key, value); }  // synchronous commit
    public String read(String key) { return leader.get(key); }               // always leader → latest
}
