```java
// ─── File: EventualStore.java ───
package com.bank.consistency;

import java.util.*;

// Eventual consistency: leader + replicas; replicas lag until propagation.
public class EventualStore {
    private final Map<String,String> leader = new HashMap<>();
    private final List<Map<String,String>> replicas = new ArrayList<>();
    private final Deque<String[]> pending = new ArrayDeque<>();

    public EventualStore(int replicaCount) {
        for (int i = 0; i < replicaCount; i++) replicas.add(new HashMap<>());
    }
    public void write(String key, String value) {
        leader.put(key, value);
        pending.add(new String[]{key, value});   // not yet on replicas
    }
    public String readLeader(String key) { return leader.get(key); }
    // read from a replica → may be stale until propagate() runs
    public String readReplica(String key) {
        return replicas.get(0).getOrDefault(key, "<stale/absent>");
    }
    // async replication: replicas converge to the leader
    public void propagate() {
        String[] c;
        while ((c = pending.poll()) != null)
            for (Map<String,String> r : replicas) r.put(c[0], c[1]);
    }
}
