// ─── File: StreamProcessor.java ───
package com.bank.processing;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// Stream: consume an unbounded flow, react per event with low latency, keep state.
public class StreamProcessor {
    private static final Logger log = Logger.getLogger("Proc");
    private final BigDecimal suspiciousThreshold;
    private final Map<String, BigDecimal> runningTotals = new HashMap<>(); // stateful

    public StreamProcessor(BigDecimal suspiciousThreshold) {
        this.suspiciousThreshold = suspiciousThreshold;
    }

    // called for EACH event as it arrives — immediate reaction
    public void onEvent(Transaction t) {
        runningTotals.merge(t.accountId(), t.amount(), BigDecimal::add);
        if (t.amount().compareTo(suspiciousThreshold) > 0) {
            log.warning(() -> "FRAUD ALERT (real-time): " + t.accountId() + " Rs." + t.amount());
        } else {
            log.info(() -> "stream processed " + t.accountId() + " Rs." + t.amount());
        }
    }
}
